"use client";

import { type ButtonHTMLAttributes, createContext, type HTMLAttributes, use, useCallback, useState } from "react";
import { cx } from "../utils/cx";

export type ToggleProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> & {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  size?: "sm" | "md";
};

/** A button that stays pressed (bold, mute, favorite). Pressed state is `aria-pressed`. */
export function Toggle({
  pressed: controlled,
  defaultPressed = false,
  onPressedChange,
  size = "md",
  className,
  onClick,
  ...rest
}: ToggleProps) {
  const [inner, setInner] = useState(defaultPressed);
  const pressed = controlled ?? inner;
  return (
    <button
      {...rest}
      type="button"
      aria-pressed={pressed}
      className={cx("hm-toggle", className)}
      data-size={size}
      onClick={(e) => {
        onClick?.(e);
        if (e.defaultPrevented) return;
        if (controlled === undefined) setInner(!pressed);
        onPressedChange?.(!pressed);
      }}
    />
  );
}

type GroupContextValue = { isOn: (value: string) => boolean; flip: (value: string) => void; size: "sm" | "md" };
const GroupContext = createContext<GroupContextValue | null>(null);

type GroupBase = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  "aria-label": string;
  size?: "sm" | "md";
};
export type ToggleGroupProps = GroupBase &
  (
    | { type?: "single"; value?: string; defaultValue?: string; onValueChange?: (value: string) => void }
    | { type: "multiple"; value?: string[]; defaultValue?: string[]; onValueChange?: (value: string[]) => void }
  );

/**
 * Related toggles in one hairline group. `single` behaves like a toolbar choice that can be cleared; `multiple` is for
 * independent formatting switches. For a required single choice use `SegmentedControl`.
 */
export function ToggleGroup(props: ToggleGroupProps) {
  const { type = "single", size = "md", className, ...more } = props;
  const { value: _v, defaultValue: _d, onValueChange: _o, ...rest } = more as Record<string, unknown>;
  const multiple = type === "multiple";
  const initial = (props as { defaultValue?: string | string[] }).defaultValue;
  const [inner, setInner] = useState<string[]>(
    initial === undefined ? [] : Array.isArray(initial) ? initial : initial ? [initial] : [],
  );
  const controlled = (props as { value?: string | string[] }).value;
  const on = controlled === undefined ? inner : Array.isArray(controlled) ? controlled : controlled ? [controlled] : [];
  const onValueChange = (props as { onValueChange?: (v: never) => void }).onValueChange;
  const flip = useCallback(
    (v: string) => {
      const next = multiple ? (on.includes(v) ? on.filter((x) => x !== v) : [...on, v]) : on.includes(v) ? [] : [v];
      if (controlled === undefined) setInner(next);
      onValueChange?.((multiple ? next : (next[0] ?? "")) as never);
    },
    [on, multiple, controlled, onValueChange],
  );
  return (
    <GroupContext value={{ isOn: (v) => on.includes(v), flip, size }}>
      <div {...(rest as HTMLAttributes<HTMLDivElement>)} role="group" className={cx("hm-toggle-group", className)} />
    </GroupContext>
  );
}

export function ToggleGroupItem({
  value,
  className,
  onClick,
  ...rest
}: Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value"> & { value: string }) {
  const ctx = use(GroupContext);
  if (!ctx) throw new Error("<ToggleGroupItem> must be inside <ToggleGroup>");
  return (
    <button
      {...rest}
      type="button"
      aria-pressed={ctx.isOn(value)}
      className={cx("hm-toggle", className)}
      data-size={ctx.size}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) ctx.flip(value);
      }}
    />
  );
}
